const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  const comparisonOperators = ['<', '<=', '>', '>=', '==', '!='];
  const productOperators = ['*', '/', '//', '%'];

  function comparison() {
    const first = sum();
    if (!comparisonOperators.includes(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (comparisonOperators.includes(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (productOperators.includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /** Collect sign prefixes iteratively, so long sign runs do not recurse. */
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  function power() {
    const base = primary();
    if (!is('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function call(token) {
    take();
    const name = token.value;
    if (name !== 'min' && name !== 'max' && name !== 'abs') {
      throw new ExprError('Unknown function', token.column);
    }
    if (is(')')) throw new ExprError('Wrong argument count', token.column);
    const args = [comparison()];
    while (is(',')) {
      if (name === 'abs') throw new ExprError('Wrong argument count', token.column);
      take();
      args.push(comparison());
    }
